/**
 * @brief A single sales record generated by a producer thread.
 *
 * Represents one transaction placed into the shared buffer.
 * The is_sentinel flag is used exclusively by the main thread after all
 * producers finish — it pushes one sentinel per consumer so each consumer
 * knows to drain and exit.
 */
struct SalesRecord {
    int day;          ///< Day of sale: 1–30
    int month;        ///< Month of sale: 1–12
    int year;         ///< Year of sale: fixed at 16 (2016)
    int store_id;     ///< Store that made the sale: 1 to p (one per producer)
    int register_num; ///< Register used: 1–6 (random)
    double amount;    ///< Sale amount in USD: $0.50–$999.99
    bool is_sentinel = false; ///< If true, signals the consuming thread to stop
};

#include "../buffer.hpp"